/** Saved report evidence only. These helpers never change company books. */
function gcf_capture(array $record,array $books):array {
 $kind=$record['kind'];if(!in_array($kind,['DAILY','CASHFLOW'],true)||empty($record['sections'][$kind==='DAILY'?'daily':'financials']))throw new DomainException('Save the financial source section to prepare a comparison.');
 $summary=$kind==='DAILY'?gd_summary($record):gm_record_summary($record,$books,$record['date']);$total=$kind==='DAILY'?($summary['expectedPositionWithMarketStockPKR']??$summary['expectedFinancialPositionPKR']??$summary['totalPKR']):$summary['totalPKR'];$rates=(array)($record['sections']['header']['data']['rates']??[]);$moves=[];$cash=0.;
 foreach((array)($books['journals']??[]) as $key=>$j){if(!in_array($j['status']??'',['Posted','Posted / Bill Pending'],true)||!in_array($j['entity']??'',['TTI','BRM','TG'],true)||!mr_valid_date((string)($j['date']??''))||$j['date']>$record['date'])continue;$amount=0.;$party=(string)($j['meta']['counterparty']??'');foreach((array)($j['lines']??[]) as $l){if(in_array((string)($l['account']??''),['1110','1120'],true))$amount+=(float)($l['debit']??0)-(float)($l['credit']??0);elseif($party==='')$party=(string)($l['counterparty']??$l['party']??$l['supplier']??$l['customer']??'');}if(abs($amount)<.005)continue;$currency=$j['entity']==='TG'?'AED':'PKR';$pk=round($amount*gm_fx($rates,$currency),2);$id=(string)($j['id']??$key);$moves[$id]=['postId'=>$id,'date'=>$j['date'],'entity'=>$j['entity'],'currency'=>$currency,'amount'=>$amount,'amountPKR'=>$pk,'sourceFingerprint'=>hash('sha256',json_encode([$j['date'],$j['entity'],$amount],JSON_THROW_ON_ERROR))];$cash+=$pk;
 }
 return ['date'=>$record['date'],'totalPKR'=>round($total,2),'cashPKR'=>round($cash,2),'rates'=>$rates,'moves'=>$moves,'capturedAt'=>gmdate('c'),'basis'=>$kind==='DAILY'?(isset($summary['expectedPositionWithMarketStockPKR'])?'Expected position with reviewed market stock and exporter forecast':'Expected financial position including exporter forecast; stock market valuation incomplete'):'Saved net trading position'];
