function gcf_comparison(array $record,array $books,array $current):array {
 $prior=array_values(array_filter((array)($books['groupManagementRecords']??[]),static fn($r)=>($r['kind']??'')===$record['kind']&&($r['date']??'')<$record['date']&&!empty($r['sections'][$record['kind']==='DAILY'?'daily':'financials'])));usort($prior,static fn($a,$b)=>strcmp($b['date'],$a['date']));
 if(!$prior)return ['available'=>false,'message'=>'First saved cash flow. The next dated cash flow will compare with this one.'];$previous=$prior[0];$old=$previous['cashflowSnapshot']??null;$legacy=!is_array($old);if($legacy){$s=$record['kind']==='DAILY'?gd_summary($previous):gm_record_summary($previous,$books,$previous['date']);$old=['date'=>$previous['date'],'totalPKR'=>$record['kind']==='DAILY'?($s['expectedPositionWithMarketStockPKR']??$s['expectedFinancialPositionPKR']??$s['totalPKR']):$s['totalPKR'],'moves'=>[],'cashPKR'=>null];}
 $rows=[];$net=0.;foreach(array_unique(array_merge(array_keys((array)$old['moves']),array_keys($current['moves']))) as $id){$a=$old['moves'][$id]??null;$b=$current['moves'][$id]??null;$row=$b??$a;if($legacy&&$row['date']<=$previous['date'])continue;$before=$a?(float)$a['amount']*gm_fx($current['rates'],$a['currency']):0.;$amount=round((float)($b['amountPKR']??0)-$before,2);if(abs($amount)<.005)continue;$journal=$books['journals'][$id]??[];$row['description']=(string)($journal['narration']??$journal['reference']??$id);$row['party']=(string)($journal['meta']['counterparty']??'');if($row['party']==='')foreach((array)($journal['lines']??[]) as $line)if(!in_array((string)($line['account']??''),['1110','1120'],true)&&($party=(string)($line['counterparty']??$line['party']??$line['supplier']??$line['customer']??''))!==''){$row['party']=$party;break;}$row['impactPKR']=$amount;$row['change']=$a?'Earlier transaction changed / removed':($row['date']<=$previous['date']?'Backdated transaction':'New transaction');$rows[]=$row;$net+=$amount;}
 usort($rows,static fn($a,$b)=>abs($b['impactPKR'])<=>abs($a['impactPKR'])?:strcmp($a['postId'],$b['postId']));$difference=round($current['totalPKR']-$old['totalPKR'],2);
 return ['available'=>true,'previousDate'=>$previous['date'],'currentDate'=>$record['date'],'previousTotalPKR'=>$old['totalPKR'],'currentTotalPKR'=>$current['totalPKR'],'differencePKR'=>$difference,'previousCashPKR'=>$old['cashPKR'],'currentCashPKR'=>$current['cashPKR'],'cashMovementPKR'=>round($net,2),'otherChangesPKR'=>round($difference-$net,2),'cashRevaluationAndCorrectionsPKR'=>$legacy?null:round($current['cashPKR']-$old['cashPKR']-$net,2),'rows'=>$rows,'legacyBaseline'=>$legacy,'basis'=>$current['basis'],'note'=>$legacy?'The previous report predates transaction snapshots. Listed movements are dated after it; earlier corrections cannot be reconstructed.':'Compares saved snapshots, including backdated entries, amendments and reversals. Internal transfers within one posting net to zero.'];
